import { getLocale as kxGetLocale } from '../i18n/index.js';
import { localeTag as kxLocaleTag } from '../i18n/formatters.js';
import { repos } from '../core/repositories.js';
import { financeMoney, normalizeProfessionalFinance, chargeCanReceivePayment, chargeCanCancel } from '../core/finance-adapter.js';
import { esc } from '../core/utils.js';
import { setAppHtml, setPrivateViewHtml, setError, toast, confirmDialog } from '../ui/components.js';
import { icon } from '../ui/icons.js';
import { contentTranslationAttrs, prewarmUserContentTranslations } from '../i18n/user-content-translation.js';

const val=f=>Object.fromEntries(new FormData(f).entries());
const dateLabel=v=>{if(!v)return 'Sin vencimiento';try{return new Intl.DateTimeFormat(kxLocaleTag(kxGetLocale()),{dateStyle:'medium'}).format(new Date(`${v}T12:00:00`));}catch{return v}};
const statusLabel=s=>({pendiente:'Pendiente',parcial:'Parcial',pagado:'Pagado',anulado:'Anulado'}[s]||s||'');
const option=(id,label)=>`<option value="${esc(id)}">${esc(label)}</option>`;
function kpi(label,value,detail=''){return `<article><span>${esc(label)}</span><strong>${esc(financeMoney(value))}</strong><small>${esc(detail)}</small></article>`}
function reportRows(rows=[]){return rows.slice(-12).reverse().map(r=>`<tr><td>${esc(r.month)}</td><td>${esc(financeMoney(r.generated))}</td><td>${esc(financeMoney(r.collected))}</td><td>${esc(financeMoney(r.expenses))}</td><td>${esc(financeMoney(r.net))}</td></tr>`).join('')}
function chargeRows(rows=[]){
 if(!rows.length)return '<div class="premium-empty"><strong>Sin cargos</strong><p>Los cargos representan importes administrativos pendientes o satisfechos. KOMBAX no procesa el cobro.</p></div>';
 return `<div class="kx-prof-fin-list">${rows.map(c=>`<article data-charge-id="${esc(c.id)}"><div class="kx-prof-fin-row-main"><span class="kx-fin-status ${esc(c.estado)}">${esc(statusLabel(c.estado))}</span><strong ${contentTranslationAttrs({contentId:c.id,contentType:'professional_finance_charge',fieldName:'concept',sourceLocale:c.source_locale||c.idioma||'',visibility:'private',auto:false})}>${esc(c.concepto)}</strong><small>${esc(dateLabel(c.vence_el))} · ${esc(financeMoney(c.importe,c.moneda))} · saldo ${esc(financeMoney(c.saldo,c.moneda))}</small></div><div class="kx-prof-fin-actions">${chargeCanReceivePayment(c)?`<button class="btn btn-primary btn-sm" type="button" data-fin-pay="${esc(c.id)}">Registrar pago</button>`:''}${chargeCanCancel(c)?`<button class="btn btn-ghost btn-sm" type="button" data-fin-cancel="${esc(c.id)}">Anular</button>`:''}</div></article>`).join('')}</div>`;
}
function serviceRows(rows=[]){return rows.length?`<div class="kx-prof-fin-list">${rows.map(s=>`<article><div class="kx-prof-fin-row-main"><span>Servicio</span><strong ${contentTranslationAttrs({contentId:s.id,contentType:'professional_service',fieldName:'name',sourceLocale:s.source_locale||s.idioma||'',visibility:'tenant'})}>${esc(s.nombre)}</strong><small>${esc(financeMoney(s.tarifa_referencia,s.moneda))}${s.descripcion?` · <span ${contentTranslationAttrs({contentId:s.id,contentType:'professional_service',fieldName:'description',sourceLocale:s.source_locale||s.idioma||'',visibility:'tenant'})}>${esc(s.descripcion)}</span>`:''}</small></div></article>`).join('')}</div>`:'<p class="muted">Aún no hay servicios o tarifas de referencia.</p>'}
function expenseRows(rows=[]){return rows.length?`<div class="kx-prof-fin-list">${rows.slice(0,20).map(e=>`<article><div class="kx-prof-fin-row-main"><span ${contentTranslationAttrs({contentId:e.id,contentType:'professional_expense',fieldName:'category',sourceLocale:e.source_locale||e.idioma||'',visibility:'private',auto:false})}>${esc(e.categoria||'Gasto')}</span><strong ${contentTranslationAttrs({contentId:e.id,contentType:'professional_expense',fieldName:'concept',sourceLocale:e.source_locale||e.idioma||'',visibility:'private',auto:false})}>${esc(e.concepto)}</strong><small>${esc(dateLabel(e.ocurrido_el))} · ${esc(financeMoney(e.importe,e.moneda))}</small></div></article>`).join('')}</div>`:'<p class="muted">Aún no hay gastos registrados.</p>'}
function noticeRows(rows=[]){return rows.length?`<div class="kx-prof-fin-notices">${rows.map(n=>`<article><span>${icon('bell',{size:18})}</span><div><strong>${esc(n.titulo||'Aviso financiero')}</strong><p>${esc(n.cuerpo||'')}</p></div></article>`).join('')}</div>`:`<div class="kx-prof-fin-ok">${icon('check',{size:18})}<span>Sin cargos vencidos pendientes de revisión.</span></div>`}

export async function renderProfessionalFinance(profileId,{onBack}={}){
 setPrivateViewHtml('<main class="kx-prof-fin"><div class="loading-card">Cargando Finanzas Profesionales…</div></main>');
 try{
  const [raw,workspace,hub]=await Promise.all([repos.kombaxProfiles.professionalFinance(profileId),repos.kombaxProfiles.professionalWorkspace(profileId),repos.kombaxProfiles.workspace(profileId)]);
  const notifications=await repos.kombaxProfiles.professionalFinanceNotifications(profileId).catch(()=>[]);
  const data=normalizeProfessionalFinance(raw,notifications);const caps=new Set(raw?.capabilities||[]);const canManage=caps.has('professional.finance.manage');
  if(data.flags.fake_club===true||data.flags.fakeClub===true)throw new Error('Aislamiento financiero inválido: se detectó un Club ficticio.');
  const clients=workspace?.clients||[],services=data.services||[],assignments=workspace?.assignments||[];
  setPrivateViewHtml(`<main class="kx-prof-fin" data-professional-profile-id="${esc(profileId)}">
   <header class="kx-managed-top"><button class="gateway-icon-button" id="prof-fin-back" type="button" aria-label="Volver">${icon('chevronLeft',{size:22})}</button><div class="kx-managed-title"><span>MI ACTIVIDAD</span><strong>Finanzas Profesionales</strong></div><div class="kx-managed-status">${esc(hub?.profile?.nombre_publico||'Profesional')}</div></header>
   <section class="kx-prof-fin-hero"><div><span>ADMINISTRACIÓN PROFESIONAL</span><h1>Tu actividad económica, separada del Club</h1><p>Registra servicios, cargos, pagos recibidos y gastos de tu actividad. KOMBAX no procesa dinero, no actúa como pasarela de pago y no genera facturas fiscales automáticas.</p></div><div class="kx-prof-fin-scope"><b>Subject</b><code>${esc(profileId)}</code><small>Sin club_id ficticio</small></div></section>
   <section class="kx-prof-fin-kpis">${kpi('Generado',data.kpis.generated,'cargos no anulados')}${kpi('Cobrado',data.kpis.collected,'pagos registrados')}${kpi('Pendiente',data.kpis.pending,'saldo administrativo')}${kpi('Gastos',data.kpis.expenses,'gastos registrados')}${kpi('Neto',data.kpis.net,'cobrado − gastos')}</section>
   <section class="premium-surface kx-prof-fin-section"><div class="kx-prof-fin-head"><div><span>AVISOS</span><h2>Notificaciones financieras</h2></div><small>Reutilizan el centro de notificaciones con subject de Perfil Profesional.</small></div>${noticeRows(data.notifications)}</section>
   ${canManage?`<section class="premium-surface kx-prof-fin-section"><div class="kx-prof-fin-head"><div><span>CATÁLOGO</span><h2>Servicios y tarifas</h2></div></div><form id="prof-fin-service" class="kx-prof-fin-form"><label>Servicio<input name="nombre" required minlength="2" maxlength="160"></label><label>Tarifa de referencia<input name="tarifa_referencia" type="number" min="0" step="0.01" value="0"></label><label>Moneda<select name="moneda"><option>EUR</option><option>USD</option><option>GBP</option></select></label><label class="wide">Descripción<textarea name="descripcion" maxlength="2000"></textarea></label><button class="btn btn-primary" type="submit">Guardar servicio</button></form>${serviceRows(services)}</section>
   <section class="premium-surface kx-prof-fin-section"><div class="kx-prof-fin-head"><div><span>CARGOS</span><h2>Registrar cargo</h2></div></div><form id="prof-fin-charge" class="kx-prof-fin-form"><label>Concepto<input name="concepto" required minlength="2" maxlength="220"></label><label>Importe<input name="importe" type="number" min="0.01" step="0.01" required></label><label>Vencimiento<input name="vence_el" type="date"></label><label>Cliente<select name="client_id"><option value="">Sin cliente</option>${clients.map(c=>option(c.id,c.nombre)).join('')}</select></label><label>Servicio<select name="service_id"><option value="">Sin servicio</option>${services.map(s=>option(s.id,s.nombre)).join('')}</select></label><label>Asignación Events<select name="assignment_id"><option value="">Sin asignación</option>${assignments.map(a=>option(a.id,a.event_name||a.assignment_type||'Asignación')).join('')}</select></label><label class="wide">Notas<textarea name="notas" maxlength="2000"></textarea></label><button class="btn btn-primary" type="submit">Crear cargo</button></form>${chargeRows(data.charges)}</section>
   <section class="premium-surface kx-prof-fin-section"><div class="kx-prof-fin-head"><div><span>GASTOS</span><h2>Registrar gasto</h2></div></div><form id="prof-fin-expense" class="kx-prof-fin-form"><label>Concepto<input name="concepto" required minlength="2"></label><label>Importe<input name="importe" type="number" min="0.01" step="0.01" required></label><label>Fecha<input name="ocurrido_el" type="date"></label><label>Categoría<input name="categoria" maxlength="80" placeholder="material, transporte…"></label><label class="wide">Notas<textarea name="notas" maxlength="1600"></textarea></label><button class="btn btn-primary" type="submit">Guardar gasto</button></form>${expenseRows(data.expenses)}</section>`:''}
   <section class="premium-surface kx-prof-fin-section"><div class="kx-prof-fin-head"><div><span>INFORME BÁSICO</span><h2>Últimos 12 meses</h2></div><small>Registro administrativo; no sustituye contabilidad ni obligaciones fiscales.</small></div><div class="kx-prof-fin-table"><table><thead><tr><th>Mes</th><th>Generado</th><th>Cobrado</th><th>Gastos</th><th>Neto</th></tr></thead><tbody>${reportRows(data.monthly)}</tbody></table></div></section>
   <section class="kx-prof-fin-disclaimer"><strong>Límite funcional R31</strong><p>No hay cobro in-app, TPV, pasarela bancaria, facturación fiscal, IVA/VeriFactu ni automatización tributaria. El pago solo se marca cuando tú registras que lo has recibido.</p></section>
  </main>`);
  document.getElementById('prof-fin-back')?.addEventListener('click',onBack);
  const mutate=async(op,payload)=>{try{await repos.kombaxProfiles.professionalFinanceMutate(op,{professional_profile_id:profileId,...payload});toast('Guardado');return renderProfessionalFinance(profileId,{onBack});}catch(e){setError(e)}};
  document.getElementById('prof-fin-service')?.addEventListener('submit',async e=>{e.preventDefault();const x=val(e.currentTarget);try{const saved=await repos.kombaxProfiles.professionalFinanceMutate('finance.service.save',{professional_profile_id:profileId,...x});const contentId=saved?.id||saved?.service_id||null;if(contentId){void prewarmUserContentTranslations([{contentId,contentType:'professional_service',fieldName:'name',text:x.nombre,visibility:'tenant'},{contentId,contentType:'professional_service',fieldName:'description',text:x.descripcion,visibility:'tenant'}]);}toast('Guardado');await renderProfessionalFinance(profileId,{onBack});}catch(err){setError(err)}});
  document.getElementById('prof-fin-charge')?.addEventListener('submit',e=>{e.preventDefault();const x=val(e.currentTarget);mutate('finance.charge.save',{...x,client_id:x.client_id||null,service_id:x.service_id||null,assignment_id:x.assignment_id||null,vence_el:x.vence_el||null})});
  document.getElementById('prof-fin-expense')?.addEventListener('submit',e=>{e.preventDefault();const x=val(e.currentTarget);mutate('finance.expense.save',{...x,ocurrido_el:x.ocurrido_el||null})});
  document.querySelectorAll('[data-fin-pay]').forEach(b=>b.addEventListener('click',()=>{const charge=data.charges.find(c=>c.id===b.dataset.finPay);if(!charge)return;const amount=window.prompt(`Importe recibido (saldo ${financeMoney(charge.saldo,charge.moneda)})`,String(charge.saldo));if(amount===null)return;mutate('finance.payment.register',{charge_id:charge.id,importe:amount,metodo:'otro'})}));
  document.querySelectorAll('[data-fin-cancel]').forEach(b=>b.addEventListener('click',()=>confirmDialog('Anular cargo','Solo se puede anular un cargo sin pagos registrados.',()=>mutate('finance.charge.cancel',{charge_id:b.dataset.finCancel}),{confirmText:'Anular cargo'})));
 }catch(e){setError(e);onBack?.()}
}
